/**
 * LECTOR-style semantic interference map (per RESEARCH.md §5.2).
 * Words in these pairs are frequently confused; the scheduler injects
 * "Discriminative Review" exercises showing both words head-to-head.
 */
export const CONFUSABLE_PAIRS: [string, string][] = [
  ["w53", "w54"],
  ["w55", "w56"],
  ["w57", "w58"],
  ["w59", "w60"],
  ["w61", "w62"],
  ["w63", "w64"],
  ["w65", "w66"],
  ["w67", "w68"],
  ["w70", "w71"],
];

const partnerMap = new Map(CONFUSABLE_PAIRS.flatMap(([a, b]) => [[a, b], [b, a]] as [string, string][]));

export function confusablePartner(wordId: string): Word | undefined {
  const pid = partnerMap.get(wordId);
  return pid ? WORDS.find((w) => w.id === pid) : undefined;
}
